package org.bukkit.event.entity;import java.util.*;import org.bukkit.entity.*; public class PotionSplashEvent {public ThrownPotion potion;public List<LivingEntity> affected=new ArrayList<>();public Map<LivingEntity,Double> intensity=new HashMap<>();public ThrownPotion getPotion(){return potion;}public Collection<LivingEntity> getAffectedEntities(){return affected;}public void setIntensity(LivingEntity e,double v){intensity.put(e,v);} }
